import socket


class IpUtil:

    IPV4_ADDRESS_FAMILY = socket.AF_INET
    IPV6_ADDRESS_FAMILY = socket.AF_INET6

    @staticmethod
    def is_valid_ipv4(ip_address):
        try:
            IpUtil._validate_ip_address(ip_address, IpUtil.IPV4_ADDRESS_FAMILY)
            return True
        except socket.error:
            return False

    @staticmethod
    def is_valid_ipv6(ip_address):
        try:
            IpUtil._validate_ip_address(ip_address, IpUtil.IPV6_ADDRESS_FAMILY)
            return True
        except socket.error:
            return False

    @staticmethod
    def _validate_ip_address(ip_address, address_family):
        socket.inet_pton(address_family, ip_address)

    @staticmethod
    def get_hostname(ip_address):
        try:
            hostname_response = socket.gethostbyaddr(ip_address)
            return IpUtil._extract_hostname(hostname_response)
        except socket.herror:
            return None

    @staticmethod
    def _extract_hostname(hostname_response):
        return hostname_response[0]
